//! The web UI for both sides of the server build.
//!
//! Not a port of a file: the build-graph half of upstream's
//! `tools/ui/CMakeLists.txt` and `scripts/ui-assets.cmake`. `-Dui=<dist>`
//! names a built SvelteKit bundle -- `make -C llama.cpp.zmake ui` writes one
//! to `llama.cpp.zmake/.ui/dist` -- and both servers embed it:
//!
//! - **the port**, through the `ui_assets` module `tools/server/ui.zig`
//!   imports, generated by `build/ui_assets.zig`;
//! - **the reference**, through the `ui.h` and `ui.cpp` that
//!   `llama.cpp.zmake/zig/ui_embed.zig` fills upstream's templates with, as
//!   `llama.cpp.zmake` builds its own `llama-server`.
//!
//! Without `-Dui` the port's table is empty and the reference compiles
//! zmake's `zig/ui-stub`, so both take upstream's no-assets path, as before.
//! The two must always be given the same bundle: `npm run build` is not
//! reproducible (`llama.cpp.zmake`'s `CLAUDE.md`, "The web UI").

const std = @import("std");
const llamacpp = @import("llamacpp.zig");

/// What the server builds take from the UI.
pub const Ui = struct {
    /// The `ui_assets` module, for every module that compiles
    /// `tools/server/http.zig`.
    port_module: *std.Build.Module,
    /// The directory holding the reference's `ui.h`.
    ref_include: std.Build.LazyPath,
    /// The reference's `ui.cpp`.
    ref_cpp: std.Build.LazyPath,
};

/// zmake's no-assets stand-in.
const ui_stub = "llama.cpp.zmake/zig/ui-stub";

/// Declares `-Dui` and `-Dui-gzip` and the steps that embed the bundle.
///
/// Parameters:
/// - `b`: the build graph.
///
/// Return: the two sides' inputs; propagates directory-read failures.
pub fn add(b: *std.Build) !Ui {
    const dist_opt = b.option([]const u8, "ui", "Embed the web UI built in this directory in both llama-servers (`make -C llama.cpp.zmake ui` writes llama.cpp.zmake/.ui/dist). Default: no UI");
    const use_gzip = b.option(bool, "ui-gzip", "gzip-compress the embedded web UI, as upstream's LLAMA_UI_GZIP (default true)") orelse true;

    const gen = b.addExecutable(.{
        .name = "ui_assets",
        .root_module = b.createModule(.{
            .root_source_file = b.path("build/ui_assets.zig"),
            .target = b.graph.host,
            // gzip of ~10 MB is slow in Debug.
            .optimize = .ReleaseFast,
        }),
    });
    const port_run = b.addRunArtifact(gen);

    const dist = dist_opt orelse {
        port_run.addArg("-");
        port_run.addArg("0");
        const out = port_run.addOutputDirectoryArg("ui_assets");
        return .{
            .port_module = b.createModule(.{ .root_source_file = out.path(b, "assets.zig") }),
            .ref_include = b.path(ui_stub),
            .ref_cpp = b.path(ui_stub ++ "/ui.cpp"),
        };
    };
    const dist_path: std.Build.LazyPath = if (std.fs.path.isAbsolute(dist)) .{ .cwd_relative = dist } else b.path(dist);
    const gzip_arg = if (use_gzip) "1" else "0";

    port_run.addDirectoryArg(dist_path);
    port_run.addArg(gzip_arg);
    const out = port_run.addOutputDirectoryArg("ui_assets");

    const embed = b.addExecutable(.{
        .name = "ui_embed",
        .root_module = b.createModule(.{
            .root_source_file = b.path("llama.cpp.zmake/zig/ui_embed.zig"),
            .target = b.graph.host,
            .optimize = .ReleaseFast,
        }),
    });
    const ref_run = b.addRunArtifact(embed);
    ref_run.addDirectoryArg(dist_path);
    ref_run.addFileArg(b.path(llamacpp.root ++ "/tools/ui/ui.h.in"));
    ref_run.addFileArg(b.path(llamacpp.root ++ "/tools/ui/ui.cpp.in"));
    ref_run.addArg(gzip_arg);
    const h = ref_run.addOutputFileArg("ui.h");
    const cpp = ref_run.addOutputFileArg("ui.cpp");

    // A directory argument is not hashed by its contents: name every file,
    // and reconfigure when any directory's listing changes -- a rebuilt
    // bundle renames `_app/immutable/bundle.*.js`.
    b.dependOnDirectoryContents(dist_path);
    var handle = try b.root.openDir(b.graph.io, dist, .{ .iterate = true });
    defer handle.close(b.graph.io);
    var walker = try handle.walk(b.allocator);
    defer walker.deinit();
    while (try walker.next(b.graph.io)) |entry| {
        const rel = b.dupe(entry.path);
        if (entry.kind == .directory) {
            b.dependOnDirectoryContents(dist_path.path(b, rel));
            continue;
        }
        port_run.addFileInput(dist_path.path(b, rel));
        ref_run.addFileInput(dist_path.path(b, rel));
    }

    return .{
        .port_module = b.createModule(.{ .root_source_file = out.path(b, "assets.zig") }),
        .ref_include = h.dirname(),
        .ref_cpp = cpp,
    };
}
